```python
from flask import Flask, jsonify

app = Flask(__name__)

# Pretend this is a "secret layer" of data
SECRET_LAYER = {
    "data": "truths beyond the veil",
    "access_token": "your_portal_key"
}

@app.route("/portal", methods=["GET"])
def portal():
    return jsonify(SECRET_LAYER)

if __name__ == "__main__":
    app.run(port=5000)
```

